    for (int num : nums) {
        freq[num]++;
        if (freq[num] == 2) result.push_back(num);
    }

    return result;
}

int quickSelect(vector<int>& nums, int k) {
    int left = 0, right = nums.size() - 1;

    while (left <= right) {
        int pivotIndex = partition(nums, left, right);

        if (pivotIndex == k - 1) return nums[pivotIndex];
        else if (pivotIndex < k - 1) left = pivotIndex + 1;
        else right = pivotIndex - 1;
    }
    return -1;
}

double myPow(double x, int n) {
    if (n == 0) return 1.0;
    if (n < 0) return 1.0 / myPow(x, -n);

    double half = myPow(x, n / 2);
    if (n % 2 == 0) return half * half;
    return half * half * x;
}

int maxSubArray(vector<int>& nums) {
    int maxSum = nums[0];
    int currentSum = nums[0];

    for (int i = 1; i < nums.size(); i++) {
        currentSum = max(nums[i], currentSum + nums[i]);
        maxSum = max(maxSum, currentSum);
    }

    return maxSum;
}

bool isAnagram(string s, string t) {
    if (s.length() != t.length()) return false;
    vector<int> count(26, 0);

    for (int i = 0; i < s.length(); i++) {
        count[s[i] - 'a']++;
        count[t[i] - 'a']--;
    }

    for (int c : count) {
        if (c != 0) return false;
    }
    return true;
}

int rabinKarp(string text, string pattern) {
    int n = text.length(), m = pattern.length();
    int base = 256, mod = 101;

    int patternHash = 0, textHash = 0;
    int h = 1;
    for (int i = 0; i < m - 1; i++) h = (h * base) % mod;

    for (int i = 0; i < m; i++) {
        patternHash = (patternHash * base + pattern[i]) % mod;
        textHash = (textHash * base + text[i]) % mod;
    }

    for (int i = 0; i <= n - m; i++) {
        if (patternHash == textHash && text.substr(i, m) == pattern) return i;
        if (i < n - m) {
            textHash = ((textHash - text[i] * h) * base + text[i + m]) % mod;
            if (textHash < 0) textHash += mod;
        }
    }
    return -1;
}

string longestPalindrome(string s) {
    string result = "";
    for (int i = 0; i < s.length(); i++) {
        // Odd length palindrome
        string s1 = expand(s, i, i);
        // Even length palindrome
        string s2 = expand(s, i, i + 1);
        if (s1.length() > result.length()) result = s1;
        if (s2.length() > result.length()) result = s2;
    }
    return result;
}

string expand(string s, int left, int right) {
    while (left >= 0 && right < s.length() && s[left] == s[right]) {
        left--;
        right++;
    }
    return s.substr(left + 1, right - left - 1);
}

ListNode* middleNode(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }

    return slow;
}

bool hasCycle(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }

    return false;
}

ListNode* reverseKGroup(ListNode* head, int k) {
    ListNode* dummy = new ListNode(0);
    dummy->next = head;
    ListNode* prev = dummy;

    while (true) {
        ListNode* tail = prev;
        for (int i = 0; i < k; i++) {
            tail = tail->next;
            if (!tail) return dummy->next;
        }
        ListNode* next = tail->next;
        ListNode* curr = prev->next;
        reverse(curr, tail);
        prev->next = tail;
        curr->next = next;
        prev = curr;
    }
}

